/donor-dashboard.script:
function render(P) {
  const esc = P.esc;
  const fmt = P.fmt;
  const str = v => (v === null || v === undefined) ? "" : String(v);

  const restaurant = (P.data.restaurants || []).find(r => r.user_id === P.viewer.id) || null;
  const rid = restaurant ? restaurant.id : null;
  const name = restaurant && restaurant.name ? restaurant.name : "Your restaurant";
  const address = restaurant && restaurant.address ? restaurant.address : "";

  const mine = (P.data.donations || []).filter(d => d && rid !== null && d.restaurant_id === rid);
  const sorted = mine.slice().sort((a, b) => str(b.posted_at).localeCompare(str(a.posted_at)));
  const recent = sorted.slice(0, 10);

  const statuses = ["published", "claimed", "confirmed", "delivered", "expired"];
  const badgeFor = s => ({
    published: "ui-badge-info",
    claimed: "ui-badge-warning",
    confirmed: "ui-badge-success",
    delivered: "ui-badge-success",
    expired: "ui-badge-danger"
  })[s] || "ui-badge-neutral";
  const labelFor = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : "Unknown";

  const countFor = s => mine.filter(d => d.status === s).length;

  const repeatBtn = sorted.length
    ? `<a class="ui-btn ui-btn-secondary" href="/quick-post?repeat=${esc(sorted[0].id)}">Repeat last donation</a>`
    : `<span class="ui-btn ui-btn-secondary is-disabled">Repeat last donation</span>`;

  const header = `
  <div class="ui-page-header">
    <div><h1>${esc(name)}</h1><p class="ui-meta">${esc(address) || "Donor dashboard"}</p></div>
    <div class="ui-actions">
      <a class="ui-btn ui-btn-primary" href="/quick-post">Post surplus food</a>
      ${repeatBtn}
    </div>
  </div>
  ${sorted.length ? `<p class="ui-meta">Repeating a donation opens Quick Post with its details filled in. You will complete a fresh handling checklist before publishing.</p>` : ""}`;

  let activity;
  if (recent.length === 0) {
    activity = `
    <section class="ui-section">
      <h2 class="ui-section-title">Recent activity</h2>
      <div class="ui-empty">
        <p class="ui-empty-title">No donations yet</p>
        <p class="ui-empty-text">Post your first surplus food and local NGOs can claim it for pickup.</p>
        <a class="ui-btn ui-btn-primary" href="/quick-post">Post surplus food</a>
      </div>
    </section>`;
  } else {
    const rows = recent.map(d => `
        <a class="ui-card ui-card-link" href="/donations/${esc(d.id)}">
          <div class="ui-card-header"><h3>${esc(str(d.food_description) || "Surplus food")}</h3><span class="ui-badge ${badgeFor(d.status)}">${esc(labelFor(d.status))}</span></div>
          <div class="ui-card-body"><p>${esc(fmt.number(d.portions || 0))} portions · Pick up by ${esc(fmt.datetime(d.pickup_by))}</p></div>
        </a>`).join("");
    activity = `
    <section class="ui-section">
      <h2 class="ui-section-title">Recent activity</h2>
      <div class="ui-stack">${rows}
      </div>
      <p class="ui-meta"><a class="ui-link" href="/donations">View all donations</a></p>
    </section>`;
  }

  const stats = `
    <section class="ui-section">
      <h2 class="ui-section-title">Status summary</h2>
      <div class="ui-grid ui-grid-4">
        ${statuses.map(s => `
        <div class="ui-stat"><span class="ui-stat-label">${esc(labelFor(s))}</span><span class="ui-stat-value">${esc(fmt.number(countFor(s)))}</span><span class="ui-stat-note">Donations</span></div>`).join("")}
      </div>
    </section>`;

  const quick = `
    <section class="ui-section">
      <h2 class="ui-section-title">Quick links</h2>
      <div class="ui-grid ui-grid-2">
        <a class="ui-card ui-card-link" href="/restaurant-preferences">
          <div class="ui-card-header"><h3>Restaurant preferences</h3></div>
          <div class="ui-card-body"><p>Cuisine, usual pickup window and alerts.</p></div>
        </a>
        <a class="ui-card ui-card-link" href="/donations">
          <div class="ui-card-header"><h3>Donation tracking</h3></div>
          <div class="ui-card-body"><p>The full list of your donations and their statuses.</p></div>
        </a>
      </div>
    </section>`;

  return `<div class="ui-page">${header}${activity}${stats}${quick}</div>`;
}

/donations.script:
function render(P) {
  const esc = (v) => P.esc(v == null ? "" : v);
  const viewer = P.viewer || {};
  const restaurantIds = (P.data.restaurants || [])
    .filter((r) => r.user_id === viewer.id)
    .map((r) => r.id);
  const donations = (P.data.donations || [])
    .filter((d) => restaurantIds.includes(d.restaurant_id))
    .sort((a, b) => String(b.posted_at || "").localeCompare(String(a.posted_at || "")));

  const STATUS = {
    published: ["ui-badge-info", "Published"],
    claimed: ["ui-badge-warning", "Claimed"],
    confirmed: ["ui-badge-success", "Confirmed"],
    delivered: ["ui-badge-success", "Delivered"],
    expired: ["ui-badge-danger", "Expired"]
  };

  const statusBadge = (s) => {
    const m = STATUS[s] || ["ui-badge-neutral", s ? String(s) : "Unknown"];
    return `<span class="ui-badge ${m[0]}">${esc(m[1])}</span>`;
  };

  const count = donations.length;
  const countText = count === 1 ? "1 donation posted" : `${count} donations posted`;

  const rows = donations.map((d) => {
    const portions = P.fmt.number(d.portions || 0);
    const pickup = d.pickup_by ? P.fmt.datetime(d.pickup_by) : "—";
    const posted = d.posted_at ? P.fmt.datetime(d.posted_at) : "—";
    return `
        <li class="ui-list-item">
          <div class="ui-list-main">
            <a class="ui-link" href="/donations/${esc(d.id)}"><strong>${esc(d.food_description || "Untitled donation")}</strong></a>
            <span class="ui-meta">${esc(portions)} portions · Pickup by ${esc(pickup)} · Posted ${esc(posted)}</span>
          </div>
          <div class="ui-list-side">
            ${statusBadge(d.status)}
            <a class="ui-btn ui-btn-secondary ui-btn-sm" href="/donations/${esc(d.id)}">Open</a>
          </div>
        </li>`;
  }).join("");

  const listOrEmpty = donations.length
    ? `<ul class="ui-list">${rows}
      </ul>`
    : `<div class="ui-empty">
        <p class="ui-empty-title">No donations yet</p>
        <p class="ui-empty-text">Post your surplus food and follow it here until it is rescued.</p>
        <a class="ui-btn ui-btn-primary" href="/quick-post">New post</a>
      </div>`;

  return `
<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>Your donations</h1>
      <p class="ui-meta">${esc(countText)}</p>
    </div>
    <div class="ui-actions">
      <a class="ui-btn ui-btn-primary" href="/quick-post">New post</a>
    </div>
  </div>

  <section class="ui-section">
    <h2 class="ui-section-title">Donations</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        ${listOrEmpty}
      </div>
    </div>
  </section>
</div>`;
}

/ngo-feed.script:
function render(P) {
  const data = P.data || {};
  const list = (k) => (Array.isArray(data[k]) ? data[k] : []);
  const esc = (v) => P.esc(v == null ? "" : v);
  const num = (n) => P.fmt.number(Number(n) || 0);
  const viewer = P.viewer || {};

  const ngo = list("ngos").find((n) => n.user_id === viewer.id) || null;
  const ngoId = ngo ? ngo.id : null;

  const claims = list("claims");
  const allocated = (did) =>
    claims
      .filter((c) => c.donation_id === did && c.status === "confirmed")
      .reduce((s, c) => s + (Number(c.portions) || 0), 0);

  const matches = list("matches").filter((m) => m.ngo_id === ngoId);

  const eligible = matches
    .map((m) => {
      const d = P.find("donations", m.donation_id);
      return d ? { d, m } : null;
    })
    .filter((x) => x && x.d.status === "published" && (Number(x.d.portions) || 0) - allocated(x.d.id) > 0);

  const eligibleIds = eligible.map((x) => x.d.id);

  const alerts = list("notifications")
    .filter((n) => n.user_id === viewer.id && eligibleIds.indexOf(n.donation_id) !== -1)
    .map((n) => ({ n, d: P.find("donations", n.donation_id) }))
    .filter((x) => x.d);

  const intro = ngo
    ? `Eligible surplus donations matched to your need and capacity. Need ${num(ngo.current_need_portions)} portions · capacity ${num(ngo.capacity_portions)} portions.`
    : "Eligible surplus donations matched to your need and capacity.";

  const alertsHtml = alerts.length
    ? `<section class="ui-section">
    <h2 class="ui-section-title">New matches</h2>
    <div class="ui-stack">
      ${alerts
        .map(
          (a) => `<div class="ui-alert ui-alert-info">
        <a class="ui-link" href="/ngo-feed#donation-${esc(a.d.id)}">${esc(a.n.message)}</a>
        <span class="ui-meta"> · ${P.fmt.datetime(a.n.created_at)}</span>
      </div>`
        )
        .join("")}
    </div>
  </section>`
    : "";

  let listHtml;
  if (!ngo) {
    listHtml = `<div class="ui-empty"><p class="ui-empty-title">No eligible nearby donations yet</p><p class="ui-empty-text">None match right now. Check back soon.</p></div>`;
  } else if (!ngo.accepting_donations) {
    listHtml = `<div class="ui-alert ui-alert-warning">Your organisation is not accepting donations right now. Update your need and capacity to see matches.</div>
    <div class="ui-empty"><p class="ui-empty-title">No eligible nearby donations yet</p><p class="ui-empty-text">None match right now.</p><a class="ui-btn ui-btn-secondary" href="/ngo-capacity">Update need and capacity</a></div>`;
  } else if (!eligible.length) {
    listHtml = `<div class="ui-empty"><p class="ui-empty-title">No eligible nearby donations yet</p><p class="ui-empty-text">None match right now. Donations that fit your need and capacity will appear here.</p></div>`;
  } else {
    listHtml = `<div class="ui-grid ui-grid-2">
      ${eligible
        .map(({ d, m }) => {
          const r = P.find("restaurants", d.restaurant_id);
          const rName = r ? r.name : "—";
          const avail = (Number(d.portions) || 0) - allocated(d.id);
          return `<div class="ui-card" id="donation-${esc(d.id)}">
        <div class="ui-card-header"><h3>${esc(d.food_description)}</h3><span class="ui-badge ui-badge-success">Open</span></div>
        <div class="ui-card-body">
          <dl class="ui-kv">
            <dt>Donor</dt><dd>${esc(rName)}</dd>
            <dt>Portions available</dt><dd>${num(avail)}</dd>
            <dt>Pickup by</dt><dd>${P.fmt.datetime(d.pickup_by)}</dd>
          </dl>
          <p class="ui-meta">${esc(m.explanation)}</p>
        </div>
        <div class="ui-card-footer"><a class="ui-btn ui-btn-primary ui-btn-sm" href="/ngo-claim">Claim</a></div>
      </div>`;
        })
        .join("")}
    </div>`;
  }

  return `<div class="ui-page">
  <div class="ui-page-header">
    <div><h1>Nearby donations</h1><p class="ui-meta">${esc(intro)}</p></div>
    <div class="ui-actions"><a class="ui-btn ui-btn-secondary" href="/ngo-capacity">Update need and capacity</a></div>
  </div>
  ${alertsHtml}
  <section class="ui-section">
    <h2 class="ui-section-title">Available to claim</h2>
    ${listHtml}
  </section>
</div>`;
}

/donations/{}.script:
function render(P) {
  const data = P.data || {};
  const arr = k => (Array.isArray(data[k]) ? data[k] : []);
  const v = P.viewer || {};
  const persona = v.persona || "";
  const esc = x => P.esc(x == null ? "" : x);
  const dash = x => (x == null || x === "" ? "—" : P.esc(x));

  const home = {
    "Donor": "/donor-dashboard",
    "NGO": "/ngo-feed",
    "Volunteer / NGO Transporter": "/volunteer-tasks",
    "Admin": "/admin-operations"
  }[persona] || "/";

  const notAvailable = () => `<div class="ui-page">
  <div class="ui-page-header"><div><h1>Donation not available</h1><p class="ui-meta">This donation cannot be shown to you.</p></div></div>
  <div class="ui-empty"><p class="ui-empty-title">Donation not available</p><p class="ui-empty-text">It may not exist, or you are not involved in it.</p><a class="ui-btn ui-btn-primary" href="${home}">Go to your home</a></div>
</div>`;

  const d = P.find("donations", P.params && P.params.id);
  if (!d) return notAvailable();

  const restaurant = arr("restaurants").find(r => r.id === d.restaurant_id) || null;
  const ngos = arr("ngos");
  const volunteers = arr("volunteers");
  const myNgo = ngos.find(n => n.user_id === v.id) || null;
  const myVol = volunteers.find(x => x.user_id === v.id) || null;
  const myRest = !!(restaurant && restaurant.user_id === v.id);

  const claimsForD = arr("claims").filter(c => c.donation_id === d.id);
  const pickupsForD = arr("pickups").filter(p => claimsForD.some(c => c.id === p.claim_id));
  const matchesForD = arr("matches").filter(m => m.donation_id === d.id);

  const isAdmin = persona === "Admin";
  const ngoInvolved = !!(myNgo && (claimsForD.some(c => c.ngo_id === myNgo.id) || matchesForD.some(m => m.ngo_id === myNgo.id)));
  const volInvolved = !!(myVol && pickupsForD.some(p => p.volunteer_id === myVol.id));

  if (!(isAdmin || myRest || ngoInvolved || volInvolved)) return notAvailable();

  const statusLabel = { published: "Published", claimed: "Claimed", confirmed: "Confirmed", delivered: "Delivered", expired: "Expired" };
  const statusClass = { published: "ui-badge-info", claimed: "ui-badge-warning", confirmed: "ui-badge-success", delivered: "ui-badge-success", expired: "ui-badge-danger" };
  const sLabel = s => statusLabel[s] || (s ? P.esc(s) : "Unknown");
  const sClass = s => statusClass[s] || "ui-badge-neutral";

  // Back link and next step per persona
  let backLink = "";
  if (persona === "Donor") backLink = `<a class="ui-link" href="/donations">Back to tracking</a>`;
  else if (persona === "NGO") backLink = `<a class="ui-link" href="/ngo-feed">Back to feed</a>`;
  else if (persona === "Volunteer / NGO Transporter") backLink = `<a class="ui-link" href="/volunteer-tasks">Back to tasks</a>`;
  else if (isAdmin) backLink = `<a class="ui-link" href="/admin-operations">Back to operations</a>`;

  let nextStep = "";
  if (myNgo && ngoInvolved && d.status === "published") {
    nextStep = `<a class="ui-btn ui-btn-primary" href="/ngo-claim">Claim this donation</a>`;
  } else if (myVol && volInvolved) {
    nextStep = `<a class="ui-btn ui-btn-primary" href="/active-delivery">Go to delivery</a>`;
  }

  // Status history, oldest first
  let events = arr("status_events")
    .filter(e => e.donation_id === d.id)
    .sort((a, b) => (a.changed_at < b.changed_at ? -1 : a.changed_at > b.changed_at ? 1 : 0));
  let timelineHtml;
  if (events.length === 0) {
    timelineHtml = `<ol class="ui-timeline"><li class="ui-timeline-item"><span class="ui-timeline-time">${P.fmt.datetime(d.posted_at)}</span><p>Posted · ${sLabel("published")}</p></li></ol>`;
  } else {
    timelineHtml = `<ol class="ui-timeline">${events.map(e =>
      `<li class="ui-timeline-item"><span class="ui-timeline-time">${P.fmt.datetime(e.changed_at)}</span><p>${sLabel(e.status)}</p></li>`
    ).join("")}</ol>`;
  }

  const photo = d.photo_name
    ? `<div class="ui-media">Photo · ${esc(d.photo_name)}</div>`
    : "";

  return `<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>${esc(d.food_description) || "Donation"}</h1>
      <p class="ui-meta"><span class="ui-badge ${sClass(d.status)}">${sLabel(d.status)}</span> ${dash(restaurant ? restaurant.name : null)}</p>
    </div>
    <div class="ui-actions">${backLink}</div>
  </div>

  <section class="ui-section">
    <h2 class="ui-section-title">Donation details</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        ${photo}
        <dl class="ui-kv">
          <dt>Food description</dt><dd>${dash(d.food_description)}</dd>
          <dt>Portions</dt><dd>${d.portions == null ? "—" : P.fmt.number(d.portions)}</dd>
          <dt>Pickup by</dt><dd>${d.pickup_by ? P.fmt.datetime(d.pickup_by) : "—"}</dd>
          <dt>Donor restaurant</dt><dd>${dash(restaurant ? restaurant.name : null)}</dd>
          <dt>Restaurant address</dt><dd>${dash(restaurant ? restaurant.address : null)}</dd>
        </dl>
      </div>
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Handling declarations</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        <dl class="ui-kv">
          <dt>Preparation time</dt><dd>${dash(d.prep_time)}</dd>
          <dt>Storage and handling</dt><dd>${dash(d.storage_handling)}</dd>
          <dt>Allergens</dt><dd>${dash(d.allergens)}</dd>
        </dl>
      </div>
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Status history</h2>
    <div class="ui-card">
      <div class="ui-card-body">${timelineHtml}</div>
    </div>
  </section>

  ${nextStep ? `<section class="ui-section"><div class="ui-actions">${nextStep}</div></section>` : ""}
</div>`;
}

/ngo-receipt.script:
function render(P) {
  const viewerId = P.viewer && P.viewer.id;
  const ngos = (P.data && P.data.ngos) || [];
  const claims = (P.data && P.data.claims) || [];
  const receipts = (P.data && P.data.receipts) || [];
  const ngo = ngos.find(n => n && n.user_id === viewerId) || null;

  // The claimed donation awaiting receipt: a claim by this NGO whose donation
  // is still 'claimed' and which has no receipt yet.
  let item = null;
  if (ngo) {
    for (const c of claims) {
      if (!c || c.ngo_id !== ngo.id) continue;
      const d = P.find('donations', c.donation_id);
      if (!d || d.status !== 'claimed') continue;
      if (receipts.some(r => r && r.claim_id === c.id)) continue;
      item = { claim: c, donation: d };
      break;
    }
  }

  const header = `
  <div class="ui-page-header">
    <div>
      <h1>Confirm received quantity</h1>
      <p class="ui-meta">The confirmed amount is what counts as rescued food.</p>
    </div>
  </div>`;

  if (!item) {
    return `<div class="ui-page">${header}
  <section class="ui-section">
    <div class="ui-empty">
      <p class="ui-empty-title">Nothing to confirm</p>
      <p class="ui-empty-text">You have no claimed donations awaiting receipt.</p>
      <a class="ui-btn ui-btn-secondary" href="/ngo-claim">Go to claims</a>
    </div>
  </section>
</div>`;
  }

  const c = item.claim;
  const d = item.donation;
  const restaurant = P.find('restaurants', d.restaurant_id);
  const restaurantName = restaurant && restaurant.name ? restaurant.name : '—';
  const claimed = Number(c.portions) || 0;
  const pickup = d.pickup_by ? P.fmt.datetime(d.pickup_by) : '—';
  const food = d.food_description ? P.esc(d.food_description) : '—';

  return `<div class="ui-page">${header}
  <section class="ui-section">
    <h2 class="ui-section-title">Claimed donation</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        <dl class="ui-kv">
          <dt>Food</dt><dd>${food}</dd>
          <dt>Donor restaurant</dt><dd>${P.esc(restaurantName)}</dd>
          <dt>Pickup by</dt><dd>${P.esc(pickup)}</dd>
          <dt>Portions claimed</dt><dd>${P.esc(P.fmt.number(claimed))}</dd>
        </dl>
      </div>
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Received quantity</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        <form class="ui-form">
          <label class="ui-field">
            <span>Portions received</span>
            <input class="ui-input" type="number" name="received_portions" min="0" max="${claimed}" step="1" value="${claimed}">
            <span class="ui-help">Cannot exceed the ${P.esc(P.fmt.number(claimed))} portions you claimed. Enter fewer if less arrived.</span>
          </label>
          <label class="ui-field">
            <span>Note (optional)</span>
            <textarea class="ui-textarea" name="note" placeholder="Anything the donor should know"></textarea>
          </label>
        </form>
      </div>
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Confirm</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        <div class="ui-actions">
          <button class="ui-btn ui-btn-primary" type="button">Confirm received</button>
          <a class="ui-btn ui-btn-secondary" href="/donations/${P.esc(d.id)}">View donation</a>
        </div>
        <p class="ui-help">Confirmation is final. Only the confirmed quantity counts as rescued food.</p>
      </div>
    </div>
  </section>
</div>`;
}

/ngo-claim.script:
function render(P) {
  const esc = v => P.esc(v == null || v === "" ? "—" : v);
  const num = v => (typeof v === "number" ? P.fmt.number(v) : esc(v));
  const data = P.data || {};
  const viewer = P.viewer || {};
  const ngo = (data.ngos || []).find(n => n.user_id === viewer.id) || null;

  // Resolve the donation: the one in the address, or the NGO's top live match from the feed.
  const reqId = P.params && P.params.id;
  let donation = null;
  if (reqId) {
    donation = P.find("donations", reqId);
  } else if (ngo) {
    const live = (data.matches || []).find(m => {
      if (m.ngo_id !== ngo.id) return false;
      const d = P.find("donations", m.donation_id);
      return d && d.status === "published";
    });
    if (live) donation = P.find("donations", live.donation_id);
  }

  const emptyState = `
  <div class="ui-page">
    <div class="ui-page-header">
      <div><h1>Claim donation</h1><p class="ui-meta">Claim all or part of a donation</p></div>
      <div class="ui-actions"><a class="ui-link" href="/ngo-feed">Back to NGO Feed</a></div>
    </div>
    <section class="ui-section">
      <div class="ui-empty">
        <p class="ui-empty-title">This donation is no longer available</p>
        <p class="ui-empty-text">It may have been claimed by other NGOs or its confirmation window has closed.</p>
        <a class="ui-btn ui-btn-primary" href="/ngo-feed">Back to feed</a>
      </div>
    </section>
  </div>`;

  if (!donation || donation.status !== "published") {
    return emptyState;
  }

  const restaurant = P.find("restaurants", donation.restaurant_id);
  const confirmedClaims = (data.claims || []).filter(c => c.donation_id === donation.id && c.status === "confirmed");
  const claimedPortions = confirmedClaims.reduce((s, c) => s + (Number(c.portions) || 0), 0);
  const total = Number(donation.portions) || 0;
  const remaining = Math.max(0, total - claimedPortions);

  const match = ngo ? (data.matches || []).find(m => m.donation_id === donation.id && m.ngo_id === ngo.id) : null;
  const explanation = match ? match.explanation : "This donation matches your current need and capacity.";

  const setting = (data.settings || []).find(s => s.key === "reservation_timeout_minutes");
  const minutes = Number(setting && setting.value) || 5;
  const clock = `${String(minutes).padStart(2, "0")}:00`;

  const unavailable = remaining <= 0;

  const errorBlock = unavailable ? `
    <div class="ui-alert ui-alert-danger">
      All portions of this donation have been reserved by other NGOs. Portions left: 0.
    </div>
    <div class="ui-actions"><a class="ui-btn ui-btn-secondary" href="/ngo-feed">Back to feed</a></div>` : "";

  const claimDisabled = unavailable ? " is-disabled" : "";
  const claimAttr = unavailable ? " disabled" : "";

  return `
<div class="ui-page">
  <div class="ui-page-header">
    <div><h1>Claim donation</h1><p class="ui-meta">Confirm before the reservation window closes</p></div>
    <div class="ui-actions"><a class="ui-link" href="/ngo-feed">Back to NGO Feed</a></div>
  </div>

  <section class="ui-section">
    <div class="ui-card">
      <div class="ui-card-header">
        <h3>${esc(donation.food_description)}</h3>
        <span class="ui-badge ui-badge-info">${num(remaining)} of ${num(total)} available</span>
      </div>
      <div class="ui-card-body">
        <dl class="ui-kv">
          <dt>Donor restaurant</dt><dd>${esc(restaurant && restaurant.name)}</dd>
          <dt>Portions still available</dt><dd>${num(remaining)}</dd>
          <dt>Pickup by</dt><dd>${esc(P.fmt.datetime(donation.pickup_by))}</dd>
          <dt>Allergens</dt><dd>${esc(donation.allergens)}</dd>
        </dl>
        <div class="ui-alert ui-alert-info">${esc(explanation)}</div>
      </div>
    </div>
  </section>

  <section class="ui-section">
    <div class="ui-grid ui-grid-2">
      <div class="ui-card">
        <div class="ui-card-header"><h3>Your claim</h3></div>
        <div class="ui-card-body">
          <form class="ui-form">
            <label class="ui-check"><input type="radio" name="claim_mode" value="all" checked${claimAttr}> Claim all (${num(remaining)} portions)</label>
            <label class="ui-check"><input type="radio" name="claim_mode" value="part"${claimAttr}> Claim part</label>
            <label class="ui-field" hidden>
              <span>Portions to claim</span>
              <input class="ui-input" type="number" name="portions" min="1" max="${esc(remaining)}" placeholder="1 to ${esc(remaining)}"${claimAttr}>
              <span class="ui-help">Between 1 and ${num(remaining)} portions still available</span>
            </label>
            <div class="ui-actions">
              <button class="ui-btn ui-btn-primary${claimDisabled}" type="button"${claimAttr}>Confirm claim</button>
            </div>
          </form>
          ${errorBlock}
        </div>
      </div>

      <div class="ui-card">
        <div class="ui-card-header"><h3>Confirmation window</h3></div>
        <div class="ui-card-body">
          <div class="ui-stat">
            <span class="ui-stat-label">Time left to confirm</span>
            <span class="ui-stat-value">${clock}</span>
            <span class="ui-stat-note">Starts at the ${num(minutes)}-minute reservation timeout</span>
          </div>
          <div class="ui-alert ui-alert-warning">
            Unconfirmed portions are released back to the feed for other NGOs when the timer runs out.
          </div>
        </div>
      </div>
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Claim result</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        <p class="ui-meta">Once you confirm, the portions reserved for ${esc(ngo && ngo.name)} and the pickup-by time appear here.</p>
        <dl class="ui-kv">
          <dt>Portions reserved</dt><dd>Not yet confirmed</dd>
          <dt>Pickup by</dt><dd>${esc(P.fmt.datetime(donation.pickup_by))}</dd>
        </dl>
      </div>
      <div class="ui-card-footer">
        <a class="ui-btn ui-btn-secondary ui-btn-sm" href="/donations/${esc(donation.id)}">View donation</a>
      </div>
    </div>
  </section>
</div>`;
}

/volunteer-tasks.script:
function render(P) {
  const data = P.data || {};
  const list = k => (Array.isArray(data[k]) ? data[k] : []);
  const esc = v => P.esc(v == null ? "–" : v);
  const viewerId = P.viewer && P.viewer.id;

  const vol = list("volunteers").find(v => v.user_id === viewerId) || null;
  const isAvailable = !!(vol && vol.available === true);
  const capacity = vol && vol.carrying_capacity_portions != null ? vol.carrying_capacity_portions : null;

  const pickups = list("pickups");
  const takenClaimIds = new Set(
    pickups.filter(p => p.status === "accepted" || p.status === "handed_over").map(p => p.claim_id)
  );
  const receiptClaimIds = new Set(list("receipts").map(r => r.claim_id));

  const availableRows = list("claims")
    .filter(c => c.status === "confirmed" && !takenClaimIds.has(c.id) && !receiptClaimIds.has(c.id))
    .map(c => ({ claim: c, donation: P.find("donations", c.donation_id) }))
    .filter(x => x.donation && x.donation.status === "claimed")
    .sort((a, b) => String(a.donation.pickup_by || "").localeCompare(String(b.donation.pickup_by || "")));

  const myPickups = vol ? pickups.filter(p => p.volunteer_id === vol.id) : [];

  const restaurantName = d => {
    const r = d ? P.find("restaurants", d.restaurant_id) : null;
    return r ? r.name : null;
  };
  const ngoName = c => {
    const n = c ? P.find("ngos", c.ngo_id) : null;
    return n ? n.name : null;
  };

  const availableCards = availableRows.map(({ claim, donation }) => `
        <div class="ui-card">
          <div class="ui-card-header"><h3>${esc(donation.food_description)}</h3><span class="ui-badge ui-badge-warning">Needs transporter</span></div>
          <div class="ui-card-body">
            <dl class="ui-kv">
              <dt>Portions</dt><dd>${esc(P.fmt.number(claim.portions != null ? claim.portions : donation.portions))}</dd>
              <dt>Pick up by</dt><dd>${esc(P.fmt.datetime(donation.pickup_by))}</dd>
              <dt>Donor</dt><dd>${esc(restaurantName(donation))}</dd>
              <dt>Receiving NGO</dt><dd>${esc(ngoName(claim))}</dd>
            </dl>
          </div>
          <div class="ui-card-footer"><a class="ui-btn ui-btn-primary ui-btn-sm" href="/active-delivery">Accept pickup</a></div>
        </div>`).join("");

  const acceptedCards = myPickups.map(p => {
    const claim = P.find("claims", p.claim_id);
    const donation = claim ? P.find("donations", claim.donation_id) : null;
    let badge;
    if (p.status === "handed_over") badge = '<span class="ui-badge ui-badge-success">Handed over</span>';
    else if (p.status === "failed") badge = '<span class="ui-badge ui-badge-danger">Failed</span>';
    else badge = '<span class="ui-badge ui-badge-info">Accepted</span>';
    const title = donation ? donation.food_description : "Pickup";
    return `
        <div class="ui-card">
          <div class="ui-card-header"><h3>${esc(title)}</h3>${badge}</div>
          <div class="ui-card-body">
            <dl class="ui-kv">
              <dt>Portions</dt><dd>${esc(P.fmt.number(claim && claim.portions != null ? claim.portions : (donation ? donation.portions : null)))}</dd>
              <dt>Pick up by</dt><dd>${esc(P.fmt.datetime(donation ? donation.pickup_by : null))}</dd>
              <dt>Donor</dt><dd>${esc(restaurantName(donation))}</dd>
              <dt>Receiving NGO</dt><dd>${esc(ngoName(claim))}</dd>
              <dt>Status</dt><dd>${esc(p.status)}</dd>
            </dl>
          </div>
          <div class="ui-card-footer"><a class="ui-btn ui-btn-secondary ui-btn-sm" href="/active-delivery">Open</a></div>
        </div>`;
  }).join("");

  return `
<div class="ui-page">
  <div class="ui-page-header">
    <div><h1>Volunteer tasks</h1><p class="ui-meta">Accept pickups when you are available.</p></div>
  </div>

  <section class="ui-section">
    <div class="ui-grid ui-grid-2">
      <div class="ui-card">
        <div class="ui-card-header"><h3>Availability</h3><span class="ui-badge ${isAvailable ? "ui-badge-success" : "ui-badge-neutral"}">${isAvailable ? "Available" : "Not available"}</span></div>
        <div class="ui-card-body">
          <form class="ui-form">
            <label class="ui-check"><input type="checkbox"${isAvailable ? " checked" : ""}> Available for pickups</label>
            <p class="ui-meta">Currently: ${isAvailable ? "Available" : "Not available"}</p>
            <div class="ui-actions"><button class="ui-btn ui-btn-secondary" type="button">Save availability</button></div>
          </form>
        </div>
      </div>

      <div class="ui-card">
        <div class="ui-card-header"><h3>Carrying capacity</h3><span class="ui-badge ui-badge-info">${capacity == null ? "Not set" : esc(P.fmt.number(capacity)) + " portions"}</span></div>
        <div class="ui-card-body">
          <form class="ui-form">
            <label class="ui-field"><span>Carrying capacity (portions)</span><input class="ui-input" type="number" min="1" value="${capacity == null ? "" : esc(capacity)}"></label>
            <span class="ui-help">Unit: portions per trip. Saved value: ${capacity == null ? "–" : esc(P.fmt.number(capacity)) + " portions"}</span>
            <div class="ui-actions"><button class="ui-btn ui-btn-primary" type="button">Save capacity</button></div>
          </form>
        </div>
      </div>
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Available pickups</h2>
    ${availableRows.length
      ? `<div class="ui-grid ui-grid-3">${availableCards}</div>`
      : `<div class="ui-empty"><p class="ui-empty-title">No pickups need a transporter right now.</p><p class="ui-empty-text">Claimed donations awaiting a transporter will appear here.</p></div>`}
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Accepted pickups</h2>
    ${myPickups.length
      ? `<div class="ui-grid ui-grid-3">${acceptedCards}</div>`
      : `<div class="ui-empty"><p class="ui-empty-title">You have not accepted any pickups yet.</p><p class="ui-empty-text">Accepted pickups will appear here with their status.</p></div>`}
  </section>
</div>`;
}

/active-delivery.script:
function render(P) {
  const esc = P.esc;
  const fdt = (v) => (v ? P.fmt.datetime(v) : "—");
  const statusLabel = (s) => {
    const map = {
      published: "Published",
      claimed: "Claimed",
      confirmed: "Confirmed",
      accepted: "Accepted",
      collected: "Collected",
      handed_over: "Handed over",
      delivered: "Delivered",
      expired: "Expired",
      failed: "Failed"
    };
    return map[s] || (s ? String(s) : "—");
  };
  const statusBadge = (s) => {
    const cls =
      s === "handed_over" || s === "delivered" ? "ui-badge-success" :
      s === "accepted" || s === "claimed" ? "ui-badge-info" :
      s === "failed" || s === "expired" ? "ui-badge-danger" : "ui-badge-neutral";
    return `<span class="ui-badge ${cls}">${esc(statusLabel(s))}</span>`;
  };

  const header = `
  <div class="ui-page-header">
    <div><h1>Active delivery</h1><p class="ui-meta">Collection and handover are confirmed here, by your own action.</p></div>
    <div class="ui-actions"><a class="ui-btn ui-btn-secondary" href="/volunteer-tasks">Back to tasks</a></div>
  </div>`;

  const vol = (P.data.volunteers || []).find((v) => v.user_id === (P.viewer && P.viewer.id));
  const pk = vol
    ? (P.data.pickups || []).find((p) => p.volunteer_id === vol.id && p.status === "accepted")
    : null;

  if (!pk) {
    return `
<div class="ui-page">
  ${header}
  <section class="ui-section">
    <div class="ui-empty">
      <p class="ui-empty-title">No active delivery</p>
      <p class="ui-empty-text">You have no accepted pickup in progress. Accept one from your tasks to start.</p>
      <a class="ui-btn ui-btn-primary" href="/volunteer-tasks">Go to Volunteer Tasks</a>
    </div>
  </section>
</div>`;
  }

  const claim = P.find("claims", pk.claim_id) || {};
  const donation = P.find("donations", claim.donation_id) || {};
  const restaurant = P.find("restaurants", donation.restaurant_id) || {};
  const ngo = P.find("ngos", claim.ngo_id) || {};
  const portions = claim.portions != null ? claim.portions : donation.portions;
  const carry = vol ? vol.carrying_capacity_portions : null;

  const events = (P.data.status_events || [])
    .filter((e) => e.donation_id === donation.id)
    .map((e) => ({ label: statusLabel(e.status), time: e.changed_at }));
  const updates = [{ label: "Pickup accepted by you", time: pk.accepted_at }, ...events]
    .filter((u) => u.time)
    .sort((a, b) => String(b.time).localeCompare(String(a.time)));

  const collected = !!pk.collected_at;
  const handedOver = pk.status === "handed_over";
  const currentLabel = handedOver ? "Handed over" : collected ? "Collected" : statusLabel(pk.status);

  const pickupCard = `
  <section class="ui-section">
    <h2 class="ui-section-title">Current pickup</h2>
    <div class="ui-card">
      <div class="ui-card-header"><h3>${esc(donation.food_description || "Donation")}</h3>${statusBadge(pk.status)}</div>
      <div class="ui-card-body">
        <dl class="ui-kv">
          <dt>Portions</dt><dd>${esc(P.fmt.number(donation.portions || 0))}</dd>
          <dt>Pickup by</dt><dd>${esc(fdt(donation.pickup_by))}</dd>
          <dt>Donor restaurant</dt><dd>${esc(restaurant.name || "—")}</dd>
          <dt>Collect from</dt><dd>${esc(restaurant.address || "—")}</dd>
          <dt>Receiving NGO</dt><dd>${esc(ngo.name || "—")}</dd>
        </dl>
      </div>
      <div class="ui-card-footer"><a class="ui-link" href="/donations/${esc(donation.id || "")}">View donation</a></div>
    </div>
  </section>`;

  const statusSection = `
  <section class="ui-section">
    <h2 class="ui-section-title">Status updates</h2>
    <div class="ui-stat">
      <span class="ui-stat-label">Current status</span>
      <span class="ui-stat-value">${esc(currentLabel)}</span>
      <span class="ui-stat-note">Updated ${esc(fdt(collected ? pk.collected_at : pk.accepted_at))}</span>
    </div>
    <ol class="ui-timeline">
      ${updates.map((u) => `<li class="ui-timeline-item"><span class="ui-timeline-time">${esc(fdt(u.time))}</span><p>${esc(u.label)}</p></li>`).join("") || ""}
    </ol>
  </section>`;

  const carryNote =
    carry != null && portions != null && portions > carry
      ? `<div class="ui-alert ui-alert-warning">This pickup is ${esc(P.fmt.number(portions))} portions, above your carrying capacity of ${esc(P.fmt.number(carry))}.</div>`
      : "";

  const portionsBlock = `
  <div class="ui-stat">
    <span class="ui-stat-label">Portions being carried</span>
    <span class="ui-stat-value">${esc(P.fmt.number(portions || 0))}</span>
    <span class="ui-stat-note">${carry != null ? `Your carrying capacity: ${esc(P.fmt.number(carry))} portions` : "Claimed for this pickup"}</span>
  </div>
  ${carryNote}`;

  const collectionStep = `
  <section class="ui-section">
    <h2 class="ui-section-title">Collection</h2>
    <div class="ui-card">
      <div class="ui-card-body ui-stack">
        ${portionsBlock}
        <p>Confirm once you have collected the food from ${esc(restaurant.name || "the donor")}. The donation is collected once confirmed.</p>
      </div>
      <div class="ui-card-footer">
        ${collected
          ? `<span class="ui-badge ui-badge-success">Collection confirmed</span>`
          : `<button class="ui-btn ui-btn-primary" type="button">Confirm collection</button>`}
      </div>
    </div>
  </section>`;

  const handoverStep = `
  <section class="ui-section">
    <h2 class="ui-section-title">Handover</h2>
    <div class="ui-card">
      <div class="ui-card-body">
        <p>Handover passes the food to ${esc(ngo.name || "the receiving NGO")}. Rescued impact is counted only after the NGO confirms the received quantity.</p>
        ${collected || handedOver ? "" : `<p class="ui-help">Available after collection is confirmed.</p>`}
      </div>
      <div class="ui-card-footer">
        ${handedOver
          ? `<span class="ui-badge ui-badge-success">Handed over</span>`
          : `<button class="ui-btn ui-btn-primary${collected ? "" : " is-disabled"}" type="button"${collected ? "" : " disabled"}>Confirm handover</button>`}
      </div>
    </div>
  </section>`;

  return `
<div class="ui-page">
  ${header}
  ${pickupCard}
  ${statusSection}
  ${collectionStep}
  ${handoverStep}
</div>`;
}

/admin-operations.script:
function render(P) {
  const esc = P.esc;
  const txt = (v) => (v === null || v === undefined || v === '') ? '—' : esc(v);
  const list = (k) => (P.data && Array.isArray(P.data[k])) ? P.data[k] : [];
  const users = list('users');
  const claims = list('claims');
  const donations = list('donations');
  const pickups = list('pickups');
  const events = list('status_events');
  const receipts = list('receipts');
  const failed = list('failed_assignments');
  const isAdmin = !!(P.viewer && P.viewer.persona === 'Admin');
  const disabled = isAdmin ? '' : ' is-disabled';
  const disAttr = isAdmin ? '' : ' disabled';

  const userName = (id) => { const u = P.find('users', id); return u && u.name ? esc(u.name) : '—'; };
  const donationOf = (id) => donations.find(d => d.id === id) || null;
  const claimOf = (id) => claims.find(c => c.id === id) || null;

  const statusBadge = (s) => {
    const cls = s === 'approved' ? 'ui-badge-success' : s === 'pending' ? 'ui-badge-warning' : s === 'suspended' ? 'ui-badge-danger' : 'ui-badge-neutral';
    const label = s ? String(s).charAt(0).toUpperCase() + String(s).slice(1) : '—';
    return `<span class="ui-badge ${cls}">${esc(label)}</span>`;
  };

  // Participants
  const order = ['pending', 'approved', 'suspended'];
  const participantRow = (u) => {
    const actions = u.status === 'approved'
      ? `<button class="ui-btn ui-btn-danger ui-btn-sm${disabled}" type="button"${disAttr}>Suspend</button>`
      : `<button class="ui-btn ui-btn-primary ui-btn-sm${disabled}" type="button"${disAttr}>Approve</button>`;
    return `<li class="ui-list-item"><div class="ui-list-main"><strong>${txt(u.name)}</strong><span class="ui-meta">${txt(u.persona)} · ${txt(u.email)}</span></div><div class="ui-list-side">${statusBadge(u.status)} ${actions}</div></li>`;
  };
  let participantsHtml = '';
  let anyParticipants = false;
  order.forEach(s => {
    const rows = users.filter(u => u.status === s);
    if (!rows.length) return;
    anyParticipants = true;
    participantsHtml += `<p class="ui-meta"><strong>${s.charAt(0).toUpperCase() + s.slice(1)} (${rows.length})</strong></p><ul class="ui-list">${rows.map(participantRow).join('')}</ul>`;
  });
  if (!anyParticipants) {
    participantsHtml = `<div class="ui-empty"><p class="ui-empty-title">Nothing to review</p><p class="ui-empty-text">No pending or existing participants right now.</p></div>`;
  }

  // Active rescues
  const activeClaims = claims.filter(c => {
    if (c.status !== 'confirmed') return false;
    if (receipts.some(r => r.claim_id === c.id)) return false;
    const d = donationOf(c.donation_id);
    return !d || d.status === 'claimed' || d.status === 'confirmed';
  });
  const rescueRow = (c) => {
    const d = donationOf(c.donation_id);
    const pk = pickups.find(p => p.claim_id === c.id && p.status === 'accepted');
    const vol = pk ? P.find('volunteers', pk.volunteer_id) : null;
    const volName = vol ? userName(vol.user_id) : 'Unassigned';
    const ngo = P.find('ngos', c.ngo_id);
    const ngoName = ngo ? txt(ngo.name) : '—';
    const evs = events.filter(e => d && e.donation_id === d.id).sort((a, b) => String(a.changed_at).localeCompare(String(b.changed_at)));
    const lastAt = evs.length ? evs[evs.length - 1].changed_at : (d ? d.posted_at : null);
    const donLink = d ? `<a class="ui-link" href="/donations/${esc(d.id)}">Donation ID ${esc(d.id)}</a>` : '<span class="ui-meta">Donation —</span>';
    return `<li class="ui-list-item"><div class="ui-list-main"><strong>${d ? txt(d.food_description) : '—'}</strong><span class="ui-meta">${donLink} · ${ngoName} · Volunteer: ${volName}</span><span class="ui-meta">${c.portions != null ? esc(P.fmt.number(c.portions)) + ' portions · ' : ''}Last update ${lastAt ? esc(P.fmt.datetime(lastAt)) : '—'}</span></div><div class="ui-list-side"><span class="ui-badge ui-badge-info">${d ? txt(d.status) : 'Confirmed'}</span></div></li>`;
  };
  let rescuesHtml = '';
  if (activeClaims.length) {
    const groups = [];
    activeClaims.forEach(c => { if (!groups.includes(c.donation_id)) groups.push(c.donation_id); });
    rescuesHtml = `<p class="ui-meta"><strong>${activeClaims.length} active rescue${activeClaims.length === 1 ? '' : 's'}</strong></p>` +
      groups.map(gid => {
        const rows = activeClaims.filter(c => c.donation_id === gid);
        return `<ul class="ui-list">${rows.map(rescueRow).join('')}</ul>`;
      }).join('');
  } else {
    rescuesHtml = `<div class="ui-empty"><p class="ui-empty-title">Nothing to review</p><p class="ui-empty-text">No rescues are in progress.</p></div>`;
  }

  // Failed assignments
  const failedRow = (f) => {
    const c = claimOf(f.claim_id);
    const d = c ? donationOf(c.donation_id) : null;
    const pk = pickups.find(p => p.id === f.pickup_id);
    const vol = pk ? P.find('volunteers', pk.volunteer_id) : null;
    const volName = vol ? userName(vol.user_id) : 'Unassigned';
    const donLink = d ? `<a class="ui-link" href="/donations/${esc(d.id)}">Donation ID ${esc(d.id)}</a>` : '<span class="ui-meta">Donation —</span>';
    return `<li class="ui-list-item"><div class="ui-list-main"><strong>${d ? txt(d.food_description) : 'Failed assignment'}</strong><span class="ui-meta">${donLink} · Assignment ${txt(f.claim_id)} · Volunteer: ${volName}</span><span class="ui-meta">Failed ${f.failed_at ? esc(P.fmt.datetime(f.failed_at)) : '—'}</span><p>${txt(f.failure_reason)}</p></div><div class="ui-list-side"><button class="ui-btn ui-btn-secondary ui-btn-sm${disabled}" type="button"${disAttr}>Resolve</button></div></li>`;
  };
  let failedHtml = '';
  if (failed.length) {
    failedHtml = `<ul class="ui-list">${failed.map(failedRow).join('')}</ul>`;
  } else {
    failedHtml = `<div class="ui-empty"><p class="ui-empty-title">Nothing to review</p><p class="ui-empty-text">No failed assignments to resolve.</p></div>`;
  }

  const notice = isAdmin ? '' : `<div class="ui-alert ui-alert-warning">Only the Admin can approve, suspend or resolve. You are viewing this screen read-only.</div>`;

  return `<div class="ui-page">
  <div class="ui-page-header">
    <div><h1>Admin Operations</h1><p class="ui-meta">Approve participants, monitor active rescues and resolve failed assignments.</p></div>
  </div>
  ${notice}
  <section class="ui-section">
    <h2 class="ui-section-title">Participants</h2>
    <div class="ui-stack">${participantsHtml}</div>
  </section>
  <section class="ui-section">
    <h2 class="ui-section-title">Active rescues</h2>
    <div class="ui-stack">${rescuesHtml}</div>
  </section>
  <section class="ui-section">
    <h2 class="ui-section-title">Failed assignments</h2>
    <div class="ui-stack">${failedHtml}</div>
  </section>
</div>`;
}

/sponsor-impact.script:
function render(P) {
  const esc = (v) => P.esc(v == null ? "" : v);
  const viewerId = P.viewer && P.viewer.id;
  const campaigns = (P.data.campaigns || []).filter((c) => c.user_id === viewerId);
  const campaign = campaigns[0] || null;
  const receipts = P.data.receipts || [];
  const receiptCount = receipts.length;

  const portions = receipts.reduce((sum, r) => {
    const n = Number(r.received_portions);
    return sum + (Number.isFinite(n) ? n : 0);
  }, 0);

  const settingRow = (P.data.settings || []).find((s) => s.key === "impact_kg_per_portion");
  const settingVal = settingRow ? Number(settingRow.value) : NaN;
  const factor = Number.isFinite(settingVal) ? settingVal : 0.35;

  const kg = portions * factor;
  const rateRaw = campaign ? Number(campaign.illustrative_cost_per_portion) : NaN;
  const rate = Number.isFinite(rateRaw) ? rateRaw : 0;
  const illustrativeCost = portions * rate;

  const hasConfirmed = receiptCount > 0 && portions > 0;

  const recognitionHtml = campaign
    ? `<div class="ui-card" style="box-shadow:0 8px 24px rgba(0,0,0,0.12)">
        <div class="ui-card-header"><h3>${esc(campaign.name)}</h3><span class="ui-badge ui-badge-success">Sponsor</span></div>
        <div class="ui-card-body"><p>${esc(campaign.recognition_text)}</p></div>
      </div>`
    : `<div class="ui-empty">
        <p class="ui-empty-title">No campaign recognition yet</p>
        <p class="ui-empty-text">Your sponsored campaign will appear here once it is set up.</p>
      </div>`;

  const emptyNote = hasConfirmed
    ? ""
    : `<div class="ui-empty">
        <p class="ui-empty-title">No confirmed deliveries yet</p>
        <p class="ui-empty-text">Portions, waste avoided and costs show zero until an NGO confirms a delivery.</p>
      </div>`;

  const statCard = (label, value, note) => `<div class="ui-card">
      <div class="ui-card-body">
        <div class="ui-stat">
          <span class="ui-stat-label">${label}</span>
          <span class="ui-stat-value">${value}</span>
          <span class="ui-stat-note">${note}</span>
        </div>
      </div>
    </div>`;

  const portionsCard = statCard(
    "Confirmed portions delivered",
    esc(P.fmt.number(portions)),
    `Derived from confirmed data · ${esc(P.fmt.number(receiptCount))} NGO-confirmed receipt${receiptCount === 1 ? "" : "s"}`
  );

  const wasteCard = statCard(
    "Estimated waste avoided",
    `${esc(kg.toFixed(1))} kg`,
    `Derived from confirmed data · ${esc(P.fmt.number(portions))} portions × ${esc(factor.toFixed(2))} kg per portion`
  );

  const costCard = statCard(
    "Illustrative costs",
    esc(P.fmt.money(illustrativeCost)),
    `Derived from confirmed data · Illustrative only, not a billed or paid amount`
  );

  return `<div class="ui-page">
  <div class="ui-page-header">
    <div>
      <h1>Sponsor Impact</h1>
      <p class="ui-meta">Figures count only NGO-confirmed deliveries.</p>
    </div>
  </div>

  <section class="ui-section">
    <h2 class="ui-section-title">Campaign recognition</h2>
    ${recognitionHtml}
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Impact summary</h2>
    ${emptyNote}
    <div class="ui-grid ui-grid-3">
      ${portionsCard}
      ${wasteCard}
      ${costCard}
    </div>
  </section>

  <section class="ui-section">
    <h2 class="ui-section-title">Assumptions</h2>
    <div class="ui-alert ui-alert-info">These assumptions are disclosed so every figure above can be checked.</div>
    <div class="ui-card">
      <div class="ui-card-body">
        <ul class="ui-list">
          <li class="ui-list-item">
            <div class="ui-list-main">
              <strong>Waste avoided factor</strong>
              <span class="ui-meta">Waste avoided = confirmed portions × ${esc(factor.toFixed(2))} kg per portion. This factor is configurable and is disclosed here.</span>
            </div>
          </li>
          <li class="ui-list-item">
            <div class="ui-list-main">
              <strong>Confirmed deliveries only</strong>
              <span class="ui-meta">Only NGO-confirmed receipts count toward portions, waste avoided and costs.</span>
            </div>
          </li>
          <li class="ui-list-item">
            <div class="ui-list-main">
              <strong>Illustrative costs</strong>
              <span class="ui-meta">Illustrative costs are estimates at ${esc(P.fmt.money(rate))} per portion. They are not actual payments, billing or invoices.</span>
            </div>
          </li>
          <li class="ui-list-item">
            <div class="ui-list-main">
              <strong>No certification or tax claims</strong>
              <span class="ui-meta">No tax or legal-benefit claim is made. This screen does not state any food safety certification.</span>
            </div>
          </li>
        </ul>
      </div>
    </div>
  </section>
</div>`;
}
